    expect(() => validatePluginName(plugin)).toThrow('The plugin "name" must be a string: 123');
  });

  it('should call validateNameString with the correct name', () => {
    const plugin = { name: 'testPlugin' };
    validatePluginName(plugin);
    expect(validateNameString).toHaveBeenCalledWith('testPlugin');
  });

  it('should return the plugin object with fullName property added', () => {
    const plugin = { name: 'testPlugin' };
    const result = validatePluginName(plugin);
    expect(result).toEqual({ name: 'testPlugin', fullName: `${NAME_PREFIX}testPlugin` });
  });
});

