describe('callStaticMethod', () => {
  let mockMethodFunc, mockPlugin, mockPlugins, mockErrorClass, mockArgs;

  beforeEach(() => {
    mockMethodFunc = jest.fn();
    mockPlugin = { name: 'testPlugin' };
    mockPlugins = [{ name: 'plugin1' }, { name: 'plugin2' }];
    mockErrorClass = class MockError {};
    mockArgs = ['arg1', 'arg2'];

    classesData.get.mockReturnValue({
      classOpts: { key: 'value' },
    });

    getMethodOpts.mockReturnValue({
      args: ['processedArg1', 'processedArg2'],
      methodOpts: { optKey: 'optValue' },
    });

    finalizePluginsOpts.mockReturnValue({
      finalizedKey: 'finalizedValue',
    });

    getPluginInfo.mockReturnValue({
      infoKey: 'infoValue',
    });
  });

  afterEach(() => {
    jest.clearAllMocks();
  });

  it('should call methodFunc with the correct arguments', () => {
    callStaticMethod(
      {
        methodFunc: mockMethodFunc,
        plugin: mockPlugin,
        plugins: mockPlugins,
        ErrorClass: mockErrorClass,
      },
      ...mockArgs
    );

    expect(classesData.get).toHaveBeenCalledWith(mockErrorClass);
    expect(getMethodOpts).toHaveBeenCalledWith(mockArgs, mockPlugin);
    expect(finalizePluginsOpts).toHaveBeenCalledWith({
      pluginsOpts: { key: 'value' },
      methodOpts: { optKey: 'optValue' },
      plugins: mockPlugins,
      plugin: mockPlugin,
    });
    expect(getPluginInfo).toHaveBeenCalledWith({
      options: { finalizedKey: 'finalizedValue' },
      ErrorClass: mockErrorClass,
      methodOpts: { optKey: 'optValue' },
      plugins: mockPlugins,
      plugin: mockPlugin,
    });
    expect(mockMethodFunc).toHaveBeenCalledWith(
      { infoKey: 'infoValue' },
      'processedArg1',
      'processedArg2'
    );
  });

  it('should handle empty args correctly', () => {
    getMethodOpts.mockReturnValue({
      args: [],
      methodOpts: { optKey: 'optValue' },
    });

    callStaticMethod(
      {
        methodFunc: mockMethodFunc,
        plugin: mockPlugin,
        plugins: mockPlugins,
        ErrorClass: mockErrorClass,
      }
    );

    expect(mockMethodFunc).toHaveBeenCalledWith(
      { infoKey: 'infoValue' }
    );
  });

  it('should throw an error if methodFunc is not provided', () => {
    expect(() => {
      callStaticMethod(
        {
          methodFunc: null,
          plugin: mockPlugin,
          plugins: mockPlugins,
          ErrorClass: mockErrorClass,
        },
        ...mockArgs
      );
    }).toThrow();
  });
});

