const { deepCloneObject } = require('../../../src/options/clone');

describe('deepCloneObject', () => {
  it('should return a deep clone of a simple object', () => {
    const input = { a: 1, b: 'test', c: true };
    const result = deepCloneObject(input);

    expect(result).toEqual(input);
    expect(result).not.toBe(input);
  });

  it('should return a deep clone of a nested object', () => {
    const input = { a: { b: { c: 42 } }, d: [1, 2, 3] };
    const result = deepCloneObject(input);

    expect(result).toEqual(input);
    expect(result).not.toBe(input);
    expect(result.a).not.toBe(input.a);
    expect(result.a.b).not.toBe(input.a.b);
    expect(result.d).not.toBe(input.d);
  });

  it('should handle objects with symbols as keys', () => {
    const symbolKey = Symbol('key');
    const input = { [symbolKey]: 'value' };
    const result = deepCloneObject(input);

    expect(result).toEqual(input);
    expect(result).not.toBe(input);
    expect(result[symbolKey]).toBe('value');
  });

  it('should handle objects with non-enumerable properties', () => {
    const input = {};
    Object.defineProperty(input, 'hidden', {
      value: 'secret',
      enumerable: false,
    });
    const result = deepCloneObject(input);

    expect(Object.getOwnPropertyDescriptor(result, 'hidden')).toEqual(
      Object.getOwnPropertyDescriptor(input, 'hidden')
    );
    expect(result.hidden).toBe('secret');
  });

  it('should handle empty objects', () => {
    const input = {};
    const result = deepCloneObject(input);

    expect(result).toEqual(input);
    expect(result).not.toBe(input);
  });

  it('should handle objects with null prototype', () => {
    const input = Object.create(null);
    input.a = 1;
    const result = deepCloneObject(input);

    expect(result).toEqual(input);
    expect(result).not.toBe(input);
    expect(Object.getPrototypeOf(result)).toBe(null);
  });

  it('should handle objects with getters and setters', () => {
    const input = {};
    Object.defineProperty(input, 'computed', {
      get() {
        return this._value;
      },
      set(value) {
        this._value = value;
      },
      enumerable: true,
    });
    input._value = 42;

    const result = deepCloneObject(input);

    expect(Object.getOwnPropertyDescriptor(result, 'computed')).toEqual(
      Object.getOwnPropertyDescriptor(input, 'computed')
    );
    expect(result._value).toBe(42);
    result.computed = 100;
    expect(result._value).toBe(100);
  });
});

